<template>
  <section class="target-page"><div class="page-head"><div><p>MONTHLY TARGETS</p><h2>月度目标配置</h2><span>为运营人员配置每月销售额与上架目标。</span></div></div><div class="target-card"><a-form :model="form" layout="vertical" @finish="save"><div class="grid"><a-form-item label="运营人员" name="operator_id" :rules="[{required:true,message:'请选择运营人员'}]"><a-select v-model:value="form.operator_id" show-search option-filter-prop="label"><a-select-option v-for="person in people" :key="person.id" :value="person.id" :label="person.real_name">{{ person.real_name }}</a-select-option></a-select></a-form-item><a-form-item label="目标月份" name="target_month" :rules="[{required:true}]"><a-date-picker v-model:value="form.target_month" picker="month" value-format="YYYY-MM" style="width:100%"/></a-form-item><a-form-item label="所属部门"><a-input v-model:value="form.department" placeholder="可选"/></a-form-item><a-form-item label="月销售额目标（USD）" name="sales_target" :rules="[{required:true,message:'请填写销售目标'}]"><a-input-number v-model:value="form.sales_target" :min="0" :precision="2" prefix="$" style="width:100%"/></a-form-item><a-form-item label="月上架数量目标"><a-input-number v-model:value="form.listing_target" :min="0" :precision="0" style="width:100%"/></a-form-item></div><a-button type="primary" html-type="submit" size="large" :loading="saving">保存月度目标</a-button></a-form><aside><h3>配置说明</h3><p>同一运营同一月份仅保留一条目标，重复保存会覆盖原配置。</p><p>日报页会实时读取对应月份目标；未配置时不会计算完成率。</p><p>销售额统一按美元（USD）口径，运营填写“本月累计销售额”，直接与月目标比较。</p></aside></div></section>
</template>
<script setup>
import { onMounted,reactive,ref } from 'vue';import dayjs from 'dayjs';import { message } from 'ant-design-vue';import { getReportPeople,saveMonthlyTarget } from '@/services/api'; const people=ref([]),saving=ref(false);const form=reactive({operator_id:null,department:'',target_month:dayjs().format('YYYY-MM'),sales_target:0,listing_target:0});async function save(){saving.value=true;try{await saveMonthlyTarget(form);message.success('月度目标保存成功')}finally{saving.value=false}}onMounted(async()=>people.value=await getReportPeople())
</script>
<style scoped>
.target-page{max-width:1100px;margin:auto}.page-head{margin-bottom:20px}.page-head p{margin:0 0 5px;color:#2f7df4;font-size:10px;font-weight:700;letter-spacing:.16em}.page-head h2{margin:0 0 6px;font-size:24px}.page-head span{color:#7e8ba1;font-size:13px}.target-card{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:25px;padding:26px;border:1px solid #dfe7f2;border-radius:12px;background:#fff}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:0 17px}.target-card aside{padding:20px;border-radius:10px;background:#f2f7ff}.target-card aside h3{margin-top:0}.target-card aside p{color:#62738e;font-size:12px;line-height:1.8}@media(max-width:800px){.target-card{grid-template-columns:1fr}.grid{grid-template-columns:1fr}}
</style>
